export function drawFarm(canvas) {
  const g = canvas.getContext("2d");
  const rect = (color, x, y, w, h) => {
    g.fillStyle = color;
    g.fillRect(x, y, w, h);
  };
  const poly = (color, points) => {
    g.fillStyle = color;
    g.beginPath();
    for (const [x, y] of points) g.lineTo(x, y);
    g.closePath();
    g.fill();
  };
  const oval = (color, x, y, rx, ry) => {
    poly(color, [[x - rx, y - ry / 2], [x - rx * .62, y - ry], [x + rx * .57, y - ry],
      [x + rx, y - ry / 2], [x + rx, y + ry / 2], [x + rx * .56, y + ry],
      [x - rx * .59, y + ry], [x - rx, y + ry / 2]].map(p => p.map(Math.round)));
  };
  const tree = (x, y, fruit) => {
    oval("#304a30", x + 6, y + 2, 24, 6);
    rect("#493926", x - 4, y - 18, 8, 19);
    rect("#a0804e", x - 3, y - 12, 2, 11);
    rect("#543c29", x - 8, y, 14, 2);
    oval("#273d29", x, y - 26, 25, 17);
    oval("#365b35", x - 1, y - 34, 23, 19);
    oval("#4e753d", x - 6, y - 40, 17, 13);
    oval("#638547", x - 9, y - 43, 12, 8);
    for (const [dx, dy] of [[-16, -47], [-8, -49], [1, -43], [-20, -36], [-8, -33], [10, -31], [16, -38], [2, -22]]) {
      rect(dy < -39 ? "#88a35b" : "#68834b", x + dx, y + dy, 4, 2);
    }
    for (const [dx, dy] of [[-15, -31], [-1, -39], [13, -26]]) {
      rect("#563f2b", x + dx, y + dy, 5, 5);
      rect(fruit, x + dx, y + dy, 4, 4);
      rect("#eed288", x + dx, y + dy, 2, 1);
    }
  };
  const flowers = (x, y, colors) => {
    oval("#345431", x, y, 18, 7);
    for (let i = 0; i < 9; i++) {
      const px = x - 13 + (i * 11) % 29;
      const py = y - 6 + (i * 5) % 10;
      rect("#7e9a54", px, py, 1, 4);
      rect(colors[i % colors.length], px - 1, py, 3, 2);
      rect("#e9c57a", px, py, 1, 1);
    }
  };

  rect("#426639", 0, 0, 320, 510);
  for (let i = 0; i < 1050; i++) {
    const x = (i * 79 + (i % 17) * 13) % 318;
    const y = (i * 53 + (i % 23) * 11) % 508;
    rect(i % 4 === 0 ? "#668849" : "#365632", x, y, 2 + i % 3, 1);
    if (i % 11 === 0) rect("#63814a", x + 1, y - 2, 1, 3);
  }
  // Đồi cây phía sau ao và đường xuyên vườn từ mép bản đồ.
  poly("#36543a", [[0, 0], [320, 0], [320, 55], [282, 44], [246, 49], [201, 36],
    [156, 41], [119, 27], [76, 36], [31, 30], [0, 42]]);
  poly("#547748", [[0, 0], [320, 0], [320, 36], [277, 25], [243, 30], [199, 17],
    [151, 23], [112, 11], [76, 23], [28, 17], [0, 32]]);
  poly("#776344", [[166, 0], [200, 0], [203, 18], [217, 30], [211, 47], [199, 59],
    [196, 75], [173, 94], [157, 88], [178, 65], [178, 52], [194, 35], [190, 24]]);
  poly("#aa905d", [[171, 0], [196, 0], [200, 20], [213, 31], [207, 46], [195, 57],
    [192, 73], [171, 92], [161, 87], [182, 66], [182, 53], [198, 35], [194, 23]]);
  for (const [x, y, color] of [[19, 40, "#c78155"], [59, 49, "#d7a366"], [103, 39, "#c88252"],
    [137, 59, "#d7a366"], [245, 51, "#d49d58"], [282, 40, "#ca8552"], [316, 62, "#d3a35e"]]) {
    tree(x, y, color);
  }
  flowers(80, 62, ["#d6a56d", "#d08e82"]);
  flowers(263, 70, ["#e4bc76", "#bf8d72"]);
  g.save();
  g.translate(0, 70);
  g.save();
  g.translate(0, 30);

  // Lối đất từ cổng, vòng lên kho và giếng.
  const path = [[0, 51], [90, 51], [90, 44], [245, 44], [245, 49], [320, 49],
    [320, 65], [200, 65], [200, 75], [128, 75], [128, 64], [0, 64]];
  poly("#6c5c3b", path.map(([x, y]) => [x, y + 2]));
  poly("#a48b58", path);
  for (let x = 2; x < 320; x += 9) {
    const y = 54 + x % 7;
    rect("#c0a46c", x, y, 3, 1);
    rect("#877048", x + 4, y + 3, 2, 1);
  }
  rect("#303d25", 11, 69, 298, 236);
  rect("#53633a", 13, 71, 294, 230);
  rect("#353c2f", 12, 300, 296, 11);
  rect("#7f7860", 12, 301, 296, 7);
  rect("#b5ac82", 12, 301, 296, 2);
  for (let x = 20; x < 307; x += 12) {
    rect("#5e5949", x, 303, 1, 5);
    rect("#91846a", x + 2, 304, 4, 1);
  }

  // Hàng rào thấp với cột có đầu sáng, chừa lối vào ở giữa.
  for (const [x, w] of [[5, 117], [198, 117]]) {
    rect("#433324", x, 67, w, 12);
    rect("#996b42", x, 68, w, 3);
    rect("#b78956", x, 73, w, 3);
    for (let post = x; post < x + w; post += 19) {
      rect("#39291e", post, 64, 5, 17);
      rect("#c39a63", post + 1, 64, 3, 4);
      rect("#88623d", post + 1, 68, 3, 11);
    }
  }

  // Kho gỗ mái ngói và cửa hai cánh.
  poly("#304a2d", [[24, 46], [90, 46], [99, 54], [93, 59], [27, 59], [18, 55]]);
  rect("#412c20", 28, 31, 60, 23);
  rect("#ae7746", 30, 33, 55, 19);
  for (let x = 32; x < 85; x += 5) rect("#8d5838", x, 34, 1, 18);
  rect("#593a28", 48, 36, 20, 18);
  rect("#d4a166", 49, 37, 18, 2);
  rect("#67442c", 57, 39, 2, 15);
  rect("#edc98a", 54, 46, 2, 1);
  rect("#edc98a", 60, 46, 2, 1);
  rect("#513b2b", 74, 38, 8, 8);
  rect("#e6bb70", 75, 39, 6, 5);
  rect("#9c6c43", 77, 39, 1, 5);
  poly("#472c29", [[20, 33], [44, 10], [70, 10], [95, 33], [91, 37], [24, 37]]);
  poly("#9b4e3b", [[24, 32], [45, 12], [69, 12], [91, 32]]);
  for (let row = 0; row < 4; row++) {
    const left = 43 - row * 5;
    const width = 29 + row * 10;
    rect("#6d382f", left, 17 + row * 5, width, 1);
    for (let x = left + 2 + (row % 2) * 3; x < left + width - 2; x += 7) {
      rect("#bf6e50", x, 18 + row * 5, 4, 1);
    }
  }
  rect("#d9835b", 45, 12, 24, 2);
  rect("#70402e", 24, 33, 67, 2);

  // Giếng đá, nước và mái gỗ.
  rect("#304a2d", 232, 48, 47, 9);
  poly("#414336", [[235, 39], [242, 35], [263, 35], [270, 39], [270, 51], [264, 55], [241, 55], [235, 51]]);
  rect("#8b8973", 237, 41, 31, 10);
  rect("#b4ae90", 237, 41, 31, 2);
  rect("#666757", 237, 46, 31, 1);
  for (let x = 243; x < 268; x += 8) {
    rect("#666757", x, 42, 1, 4);
    rect("#666757", x + 3, 47, 1, 4);
  }
  rect("#32504f", 241, 38, 23, 4);
  rect("#64a49b", 245, 38, 14, 2);
  rect("#573b29", 239, 24, 3, 17);
  rect("#573b29", 264, 24, 3, 17);
  poly("#463126", [[231, 27], [242, 15], [262, 15], [274, 27], [273, 30], [232, 30]]);
  poly("#ac7547", [[235, 26], [243, 17], [262, 17], [270, 26]]);
  rect("#d3a368", 243, 17, 19, 2);
  rect("#785338", 236, 25, 33, 2);

  // Thùng gỗ, bao hạt giống và bậc vào kho.
  rect("#725438", 45, 54, 27, 3);
  rect("#c5a16b", 47, 54, 22, 1);
  for (const [x, y] of [[88, 43], [97, 47], [217, 47]]) {
    rect("#533826", x, y, 10, 10);
    rect("#a47347", x + 1, y + 1, 8, 8);
    rect("#d2a569", x + 1, y + 2, 8, 1);
    rect("#704930", x + 1, y + 5, 8, 1);
    rect("#c49761", x + 2, y + 1, 1, 8);
  }
  g.restore();

  // Mặt ao nhiều lớp, bờ đá, bèo và một chú vịt.
  const pond = [[106, 44], [118, 33], [146, 23], [174, 23], [183, 29], [200, 32],
    [211, 43], [211, 53], [199, 66], [179, 70], [151, 72], [144, 68], [121, 67], [106, 57]];
  poly("#314c36", pond.map(([x, y]) => [x + 3, y + 4]));
  poly("#a2986b", pond);
  poly("#446f66", [[109, 46], [121, 36], [147, 27], [173, 27], [184, 33], [199, 36],
    [207, 45], [207, 52], [196, 62], [177, 66], [152, 68], [144, 64], [122, 63], [110, 55]]);
  poly("#365d5c", [[119, 49], [137, 38], [172, 34], [197, 41], [203, 51], [193, 60],
    [148, 64], [128, 58]]);
  for (const [x, y, w] of [[127, 43, 7], [137, 55, 12], [153, 35, 10], [173, 59, 9], [188, 47, 11], [159, 60, 4]]) {
    rect("#679387", x, y, w, 1);
    rect("#4c7b72", x - 2, y + 2, w - 1, 1);
  }
  for (const [x, y] of [[118, 55], [124, 57], [190, 58], [195, 55]]) {
    oval("#68864a", x, y, 4, 2);
    rect("#b7af68", x, y - 2, 2, 1);
  }
  oval("#76978a", 165, 51, 13, 2);
  oval("#e4d3a8", 164, 47, 8, 4);
  rect("#fff0c9", 167, 41, 5, 5);
  rect("#d69a54", 172, 43, 3, 2);
  rect("#463828", 170, 42, 1, 1);

  tree(23, 55, "#c58150");
  tree(96, 42, "#d1a15b");
  tree(229, 45, "#d2a15d");
  tree(302, 64, "#cd8154");
  flowers(76, 22, ["#e8c16f", "#cf8d76"]);
  flowers(272, 20, ["#e9c989", "#c58c75"]);
  flowers(221, 70, ["#c58474", "#e3b6a0"]);

  // Hàng rào tiền cảnh và lối ra giữa hai bồn hoa.
  for (const [left, width] of [[5, 120], [195, 120]]) {
    rect("#3f3325", left, 343, width, 9);
    rect("#9d7449", left, 344, width, 2);
    rect("#b68d57", left, 348, width, 2);
    for (let x = left; x < left + width; x += 19) {
      rect("#463626", x, 341, 5, 14);
      rect("#be935e", x + 1, 341, 3, 3);
      rect("#81603c", x + 1, 344, 3, 9);
    }
  }
  poly("#9b8253", [[140, 337], [179, 337], [188, 360], [132, 360]]);
  for (const [x, y, w] of [[150, 341, 16], [157, 348, 20], [139, 355, 16], [169, 355, 13]]) {
    oval("#b49d71", x + w / 2, y, w / 2, 2);
  }
  flowers(111, 352, ["#e7bb6b", "#d68a77"]);
  flowers(206, 351, ["#e5b975", "#dfaca0"]);
  g.restore();

  // Đồng cỏ dưới ruộng, bãi chăn cừu và con đường đi tiếp ra ngoài.
  poly("#537443", [[0, 443], [48, 432], [97, 438], [127, 452], [180, 451], [220, 438],
    [276, 439], [320, 429], [320, 510], [0, 510]]);
  poly("#80704a", [[132, 430], [188, 430], [200, 449], [215, 456], [227, 472], [229, 510],
    [190, 510], [191, 482], [177, 469], [155, 458]]);
  poly("#ab925c", [[137, 430], [184, 430], [196, 452], [212, 459], [224, 475], [225, 510],
    [194, 510], [195, 481], [180, 466], [158, 455]]);
  for (const [x, y, w] of [[158, 438, 17], [166, 448, 19], [192, 462, 13], [199, 474, 17], [199, 493, 17], [204, 506, 16]]) {
    oval("#c1a875", x + w / 2, y, w / 2, 2);
  }
  oval("#405d38", 82, 476, 63, 27);
  oval("#69854b", 79, 472, 56, 22);
  for (const [x, y] of [[51, 470], [88, 460], [105, 480]]) {
    oval("#425938", x + 2, y + 6, 12, 4);
    rect("#514333", x - 5, y + 3, 2, 5);
    rect("#514333", x + 4, y + 3, 2, 5);
    oval("#ded3ab", x, y, 10, 6);
    oval("#f4e7c1", x - 2, y - 2, 7, 4);
    rect("#5d4d3c", x + 7, y - 3, 5, 6);
    rect("#e1caa4", x + 10, y - 2, 1, 1);
  }
  tree(285, 490, "#ca8257");
  flowers(125, 491, ["#e8c16f", "#cf8d76"]);
  flowers(250, 504, ["#e8c16f", "#cf8d76"]);
  flowers(27, 501, ["#d7947e", "#e0bc79"]);
}
